# Step 6: plain-language sampling appendix for the OSF registration.
# Writes study/reports/prereg_sampling_appendix.md. Contains rules, counts, seeds and checksums;
# no question text, answer text or ids.
source("study/scripts/_common.R")
run <- start_run("06")
cfg <- run$cfg
verify_frozen(cfg)

attrition <- readr::read_csv(file.path(cfg$paths$frame_dir, "attrition.csv"), show_col_types = FALSE)
edits <- readr::read_csv(file.path(cfg$paths$frame_dir, "display_edits.csv"), col_types = "ccc")
q_edits <- readr::read_csv(file.path(cfg$paths$frame_dir, "question_display_edits.csv"), col_types = "ccc")
fq <- readRDS(file.path(cfg$paths$frame_dir, "frame_questions.rds"))
fa <- readRDS(file.path(cfg$paths$frame_dir, "frame_answers.rds"))
fr <- readRDS(file.path(cfg$paths$reserved_dir, "frame_remaining.rds"))
git <- git_info()

n_a <- nrow(fa)
pct <- function(k, n) sprintf("%d of %s (%.1f%%)", k, format(n, big.mark = ","), 100 * k / n)
label_tab <- tibble(label = cfg$guaranteed_labels,
                    frame = purrr::map_int(label_column_names(label), ~ sum(fq[[.x]])),
                    after_reserved_sets = purrr::map_int(label_column_names(label), ~ sum(fr[[.x]]))) |>
  arrange(frame)
not_guaranteed <- tibble(label = setdiff(cfg$scenario_labels, cfg$guaranteed_labels)) |>
  mutate(frame = purrr::map_int(label_column_names(label), ~ sum(fq[[.x]]))) |> arrange(desc(frame))
sets <- purrr::map_dfr(cfg$reserved_sets, ~ tibble(set = .x$name, size = .x$size, human = .x$n_human, ai = .x$n_ai))
checks <- tibble(file = names(unlist(cfg$frozen_checksums)), md5 = unname(unlist(cfg$frozen_checksums)))
f <- cfg$filters

out <- c(
  "# Sampling appendix: question and human-answer selection", "",
  glue("Generated by `study/scripts/06_prereg_export.R` on {format(Sys.Date())} from commit `{git$commit}`",
       "{if (isTRUE(git$uncommitted_changes)) ' (with uncommitted changes in the working tree)' else ''}. ",
       "Data: CareerNet {cfg$frame_version}, general domain. The full pipeline (R code, tests, configuration and run logs) is in the project repository."), "",
  "## 1. Eligibility frame", "",
  "Filters apply to answers, cumulatively; a question remains eligible while at least one of its answers does.", "",
  md_table(transmute(attrition, Step = step, Rule = rule, Questions = n_questions, Answers = n_answers)), "",
  glue("Exclusion rule 1 (step e) removes prompts written by CareerVillage rather than by a real asker: a question is removed when its title plus body, with HTML removed, matches this case-insensitive regular expression:"), "",
  paste0("    ", f$platform_prompt_pattern), "",
  "The pattern matches 79 questions in the full release; none remain after the date window, so the step is a safeguard. There are no manual frame exclusions (step g): a reading sample of frame questions was used to write the exclusion rules, rule 1 is applied to the frame automatically, and rules 2–4 are applied by screening the drawn sample (Section 5).", "",
  glue("The frame was then frozen: the files below were checksummed (Section 8), and the scripts that build the frame and reserved sets refuse to run while it is frozen."), "",
  "## 2. Reserved sets", "",
  "Before the study draw, four sets were removed from the frame by seeded simple random sampling, in this order, each from what the previous ones left. The planned version (human or AI answer) was assigned at random within each set.", "",
  md_table(sets), "",
  glue("This leaves {nrow(fr)} questions as the sampling frame for the study draw."), "",
  "## 3. Study draw: coverage floor", "",
  glue("- Sample size: n = {cfg$study_n} questions."),
  glue("- Guaranteed labels: the {length(cfg$guaranteed_labels)} scenario labels with at least {(cfg$guaranteed_rule_multiplier %||% 10) * cfg$floor} eligible questions ({cfg$guaranteed_rule_multiplier %||% 10} × the floor). Each must appear in at least {cfg$floor} sampled questions (the floor). A question with several labels counts toward each."),
  "- Procedure: go through the guaranteed labels from rarest to most common (count in the sampling frame). If fewer than the floor of the already selected questions carry the label, draw the shortfall at random from unselected questions carrying it. Fill the remaining slots by simple random sampling from all unselected questions.",
  glue("- Inclusion probabilities: estimated by re-running the whole draw {format(cfg$inclusion_reps, big.mark = ',')} times with derived seeds; each question's probability is the share of runs that select it. Analysis weights are 1 / inclusion probability, normalized to mean 1 over the sample. Screening (Section 5) is not reflected in these probabilities."),
  "- Occupation codes and CareerNet reasoning labels play no part in selection.", "",
  md_table(rename(label_tab, `Guaranteed label` = label, `Questions in frame` = frame, `In sampling frame` = after_reserved_sets)), "",
  glue("Not guaranteed (questions in frame): {paste0(not_guaranteed$label, ' (', not_guaranteed$frame, ')', collapse = '; ')}."), "",
  "## 4. Human answer", "",
  glue("Each question's human answer is drawn uniformly at random from its eligible answers (seeded; Section 6). Eligible answers per question in the frame: median {median(fq$n_eligible_answers)}, range {min(fq$n_eligible_answers)}–{max(fq$n_eligible_answers)}."), "",
  "## 5. Screening and replacement (exclusion rules 2–4)", "",
  "After the draw, a screener reads each drawn question (title and display text only, never the answers) and marks each rule TRUE or FALSE. A question is excluded when any rule applies:", "",
  paste0("- **Rule ", str_remove(names(SCREENING_RULES), "rule"), ":** ", SCREENING_RULES), "",
  "Replacement, applied to excluded questions in draw order:", "",
  "1. If removing the question drops one or more guaranteed labels below the floor, it is replaced by the next question in the rarest such label's replacement queue; otherwise by the next question in the general queue.",
  "2. If a guaranteed label is still below the floor (one exclusion dropped two labels at once), the most recently drawn question selected by random fill whose removal would drop no guaranteed label below the floor is swapped out for the next question in that label's queue (rarest short label first), and logged as a floor swap. This repeats until every guaranteed label meets the floor, so n stays the same. If no such question exists, the procedure stops with an error.",
  "3. Queues skip questions already selected, excluded or swapped out. The general queue is a seeded random ordering of every unselected question in the sampling frame; each guaranteed label has its own seeded queue of unselected questions carrying it. All queues are fixed at the time of the draw.",
  "4. Replacements and swapped-in questions are screened in the next round, with the same rules. Rounds repeat until a round has no exclusions. Every exclusion and swap is logged with the round, the rules triggered and the replacement.", "",
  "## 6. Seeds", "",
  "All random steps use R's Mersenne-Twister generator (normal kind Inversion, sample kind Rejection). A stage seed is `derive_seed(x, stage)`: the first 7 hexadecimal digits of the MD5 hash of the text `\"<x>:<stage>\"`, read as an integer. Before every draw the questions are put in a fixed order (numeric question id).", "",
  glue("- **Frame, reading sample, reserved sets and human-answer choice:** master seed {cfg$master_seed} (stages `reading_sample`, `reserve_sets`, `human_answer`). These were fixed before registration."),
  "- **Real study draw:** `study_master_seed = strtoi(first 7 hex digits of md5(normalized DOI), 16)`, where the DOI is this registration's OSF DOI, normalized by trimming whitespace, lowercasing, and removing a leading `https://doi.org/`, `http://doi.org/`, `doi.org/` or `doi:`. The MD5 is of the text itself. The draw (`study_draw`), the inclusion-probability runs (`inclusion_rep_1` … `inclusion_rep_N`) and the replacement queues (`replacement_queue_general`, `replacement_queue_<label>`) all derive from it. The draw cannot run until the registration (and so the DOI) exists.",
  "- Dry runs used to test the procedure before registration use the master seed with a different draw stage name and never the DOI seed.", "",
  "## 7. Display cleaning of human answers and questions", "",
  "Raters and the answer-generation step see display text; the original text is kept alongside it. HTML is converted to plain text (entities decoded, paragraph breaks kept). Only the following are removed; no wording is changed, no typos are fixed and no advice is removed.", "",
  glue("- **URLs** (text starting with http://, https://, ftp:// or www.) are removed: {pct(sum(str_detect(coalesce(fa$answer_body_raw, ''), URL_PATTERN)), n_a)} frame answers contained one."),
  glue("- **Opening salutation** (a first line or leading phrase such as \"Hi,\", \"Hello [name],\", \"Hey there!\", \"Dear student,\"): {pct(sum(edits$part == 'opening'), n_a)} answers."),
  glue("- **Closing sign-off, signature or pleasantry**: final lines that are only a valediction and/or a name (\"Best,\", \"Sincerely, [name]\", \"- [name]\") or only a closing pleasantry, optionally followed by a name. Pleasantries: {paste0('\"', cfg$closing_pleasantries, '\"', collapse = ', ')}. Never removed inside a longer sentence or anywhere but the last line. {pct(sum(edits$part == 'closing'), n_a)} answers."),
  glue("- **List markers**: a line starting with \"-\", \"*\", \"•\", \"–\" or a one- or two-digit number followed by \".\" or \")\" loses that marker and the space after it; each item stays on its own line and its words are unchanged. HTML list items become their own lines without markers. {pct(sum(edits$part == 'list_marker'), n_a)} answers."),
  glue("- Answers with any of these edits: {pct(n_distinct(edits$answer_id), n_a)}."),
  glue("- **Question hashtags** (\"#word\", \"#word-word\", added by the platform) are removed: {pct(nrow(q_edits), nrow(fq))} questions; {sum(coalesce(fq$question_text_display, '') == '')} bodies are empty afterwards and the title carries the question."),
  glue("- The AI answer's target length is the human answer's display word count ± {cfg$target_words_tolerance * 100}%."), "",
  "## 8. Frozen files", "",
  glue("Frozen at {cfg$frozen_at %||% 'NOT FROZEN'}. MD5 checksums:"), "",
  md_table(checks), ""
)

report_path <- file.path(cfg$paths$reports_dir, "prereg_sampling_appendix.md")
writeLines(out, report_path)
write_run_log(file.path(cfg$paths$logs_dir, glue("{run$run_id}.yml")), run$run_id, "06_prereg_export.R",
              seeds = list(master_seed = cfg$master_seed), config = cfg,
              input_files = c(config = run$config_path, attrition = file.path(cfg$paths$frame_dir, "attrition.csv"),
                              display_edits = file.path(cfg$paths$frame_dir, "display_edits.csv"),
                              question_display_edits = file.path(cfg$paths$frame_dir, "question_display_edits.csv"),
                              frame_questions = file.path(cfg$paths$frame_dir, "frame_questions.rds"),
                              frame_answers = file.path(cfg$paths$frame_dir, "frame_answers.rds"),
                              frame_remaining = file.path(cfg$paths$reserved_dir, "frame_remaining.rds")),
              frame_version = cfg$frame_version, outputs = c(report = report_path))
message("Appendix: ", report_path)
